/* 通話頁半透明毛玻璃 */
background: rgba(10,10,15,0.85) !important;
backdrop-filter: blur(20px);
-webkit-backdrop-filter: blur(20px);

1788263885359.bubbleCss:
/* ======= 對方bubble ======= */
.bubble.them {
    padding: 8px 8px;
    font-size: 14px;
    line-height: 1;
    background: rgba(233, 233, 233, 0.8);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(212, 212, 212, 0.5);
    color: #4a3b40;
    border-radius: 30px;
    box-shadow: 0 2px 8px rgba(107, 78, 88, 0.06),
                inset 2px 2px 5px rgba(255, 255, 255, 1);
}

/* ======= 我的bubble ======= */
.bubble.me {
    padding: 8px 8px;
    font-size: 14px;
    line-height: 1;
    background: rgba(246, 205, 197, 0.8);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(244, 196, 210, 0.5);
    color: #4a3b40;
    border-radius: 30px;
    box-shadow: 0 4px 14px rgba(212, 130, 156, 0.18),
                inset 2px 2px 5px rgba(255, 255, 255, 1);
}
